import{_ as i,a0 as d,w as s,s as p,I as t,x as r,a1 as a,A as o,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"在 Fedora 中使用 FreeMind 介紹你自己 | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora 中使用 FreeMind 介紹你自己 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora 中使用 FreeMind 介紹你自己 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora 中使用 FreeMind 介紹你自己 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190123 Mind map yourself using FreeMind and Fedora","title":"在 Fedora 中使用 FreeMind 介紹你自己","tag":"201903","desc":""},"relativePath":"201903/20190123 Mind map yourself using FreeMind and Fedora.md","filePath":"[post].md"}'),f={name:"201903/20190123 Mind map yourself using FreeMind and Fedora.md"};function m(u,e,g,F,M,x){const n=d("Link");return s(),p("div",null,[e[24]||(e[24]=t("h1",{id:"在-fedora-中使用-freemind-介紹你自己",tabindex:"-1"},[r("在 Fedora 中使用 FreeMind 介紹你自己 "),t("a",{class:"header-anchor",href:"#在-fedora-中使用-freemind-介紹你自己","aria-label":"Permalink to “在 Fedora 中使用 FreeMind 介紹你自己”"},"​")],-1)),e[25]||(e[25]=t("p",null,[t("img",{src:"https://fedoramagazine.org/wp-content/uploads/2019/01/freemind-816x345.jpg",alt:""})],-1)),t("p",null,[e[1]||(e[1]=r("介紹你自己的思維導圖，一開始聽起來有些牽強。它是關於神經通路麼？還是心靈感應？完全不是。相反，自己的思維導圖是一種在視覺上向他人描述自己的方式。它還展示了你拿來描述自己的特徵之間的聯繫。這是一種以聰明又同時可控的與他人分享信息的有用方式。你可以使用任何思維導圖應用來做到。本文向你展示如何使用 Fedora 中提供的 ",-1)),a(n,{href:"http://freemind.sourceforge.net/wiki/index.php/Main_Page"},{default:o(()=>[...e[0]||(e[0]=[r("FreeMind",-1)])]),_:1}),e[2]||(e[2]=r("。",-1))]),e[26]||(e[26]=t("h3",{id:"獲取應用",tabindex:"-1"},[r("獲取應用 "),t("a",{class:"header-anchor",href:"#獲取應用","aria-label":"Permalink to “獲取應用”"},"​")],-1)),t("p",null,[e[4]||(e[4]=r("FreeMind 已經出現有一段時間了。雖然 UI 有點過時，應該做一些更新了，但它是一個功能強大的應用，提供了許多構建思維導圖的選項。當然，它是 100％ 開源的。還有其他思維導圖應用可供 Fedora 和 Linux 用户使用。查看",-1)),a(n,{href:"https://fedoramagazine.org/three-mind-mapping-tools-fedora/"},{default:o(()=>[...e[3]||(e[3]=[r("此前一篇涵蓋多個思維導圖選擇的文章",-1)])]),_:1}),e[5]||(e[5]=r("。",-1))]),t("p",null,[e[7]||(e[7]=r("如果你運行的是 Fedora Workstation，請使用“軟件”應用從 Fedora 倉庫安裝 FreeMind。或者在終端中使用這個 ",-1)),a(n,{href:"https://fedoramagazine.org/howto-use-sudo/"},{default:o(()=>[...e[6]||(e[6]=[r("sudo",-1)])]),_:1}),e[8]||(e[8]=r(" 命令：",-1))]),e[27]||(e[27]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install freemind</span></span></code></pre></div><p>你可以從 Fedora Workstation 中的 GNOME Shell Overview 啓動應用。或者使用桌面環境提供的應用啓動服務。默認情況下，FreeMind 會顯示一個新的空白腦圖：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/01/Screenshot-from-2019-01-19-15-17-04-1024x736.png" alt=""></p><p><em>FreeMind 初始（空白）思維導圖</em></p><p>腦圖由鏈接的項目或描述（節點）組成。當你想到與節點相關的內容時，只需創建一個與其連接的新節點即可。</p><h3 id="做你自己的腦圖" tabindex="-1">做你自己的腦圖 <a class="header-anchor" href="#做你自己的腦圖" aria-label="Permalink to “做你自己的腦圖”">​</a></h3><p>單擊初始節點。編輯文本並按回車將其替換為你的姓名。你就能開始你的思維導圖。</p><p>如果你必須向某人充分描述自己，你會怎麼想？可能會有很多東西。你平時做什麼？你喜歡什麼？你不喜歡什麼？你有什麼價值？你有家庭嗎？所有這些都可以在節點中體現。</p><p>要添加節點連接，請選擇現有節點，然後單擊“Insert”，或使用“燈泡”圖標作為新的子節點。要在與新子級相同的層級添加另一個節點，請使用回車。</p><p>如果你弄錯了，別擔心。你可以使用 <code>Delete</code> 鍵刪除不需要的節點。內容上沒有規則。但是最好是短節點。它們能讓你在創建導圖時思維更快。簡潔的節點還能讓其他瀏覽者更輕鬆地查看和理解。</p><p>該示例使用節點規劃了每個主要類別：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/01/Screenshot-from-2019-01-19-15-32-38-1024x736.png" alt=""></p><p><em>個人思維導圖，第一級</em></p><p>你可以為這些區域中的每個區域另外迭代一次。讓你的思想自由地連接想法以生成導圖。不要擔心“做得正確“。最好將所有內容從頭腦中移到顯示屏上。這是下一級導圖的樣子。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/01/Screenshot-from-2019-01-19-15-38-00-1024x736.png" alt=""></p><p><em>個人思維導圖，第二級</em></p><p>你可以以相同的方式擴展任何這些節點。請注意你在示例中可以瞭解多少有關 “John Q. Public” 的信息。</p><h3 id="如何使用你的個人思維導圖" tabindex="-1">如何使用你的個人思維導圖 <a class="header-anchor" href="#如何使用你的個人思維導圖" aria-label="Permalink to “如何使用你的個人思維導圖”">​</a></h3><p>這是讓團隊或項目成員互相介紹的好方法。你可以將各種格式和顏色應用於導圖以賦予其個性。當然，這些在紙上做很有趣。但是在 Fedora 中安裝一個就意味着你可以隨時修復錯誤，甚至可以在你改變的時候做出修改。</p><p>祝你在探索個人思維導圖上玩得開心！</p><hr>',21)),t("p",null,[e[10]||(e[10]=r("via: ",-1)),a(n,{href:"https://fedoramagazine.org/mind-map-yourself-using-freemind-and-fedora/"},{default:o(()=>[...e[9]||(e[9]=[r("https://fedoramagazine.org/mind-map-yourself-using-freemind-and-fedora/",-1)])]),_:1})]),t("p",null,[e[15]||(e[15]=r("作者：",-1)),a(n,{href:"https://fedoramagazine.org/author/pfrields/"},{default:o(()=>[...e[11]||(e[11]=[r("Paul W. Frields",-1)])]),_:1}),e[16]||(e[16]=r(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[12]||(e[12]=[r("lujun9972",-1)])]),_:1}),e[17]||(e[17]=r(" 譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:o(()=>[...e[13]||(e[13]=[r("geekpi",-1)])]),_:1}),e[18]||(e[18]=r(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:o(()=>[...e[14]||(e[14]=[r("wxy",-1)])]),_:1})]),t("p",null,[e[21]||(e[21]=r("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[19]||(e[19]=[r("LCTT",-1)])]),_:1}),e[22]||(e[22]=r(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:o(()=>[...e[20]||(e[20]=[r("Linux中國",-1)])]),_:1}),e[23]||(e[23]=r(" 榮譽推出",-1))])])}const h=i(f,[["render",m]]);export{b as __pageData,h as default};
